import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.BwxVc06z.js";const _=JSON.parse('{"title":"ImpairmentsDetector","description":"","frontmatter":{},"headers":[],"relativePath":"tests/impairments_detector.md","filePath":"tests/impairments_detector.md"}'),r={name:"tests/impairments_detector.md"};function o(n,t,i,c,l,p){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="impairmentsdetector" tabindex="-1">ImpairmentsDetector <a class="header-anchor" href="#impairmentsdetector" aria-label="Permalink to &quot;ImpairmentsDetector&quot;">​</a></h1><p>Click-protocol impairments and security flags</p><p><strong>13/13 passed</strong> in 164ms</p><table tabindex="0"><thead><tr><th>Test</th><th>What it does</th><th>Result</th></tr></thead><tbody><tr><td><code>test_afterpulse_qber</code></td><td>Afterpulsing raises both gain and QBER (Papapanos et al. arXiv:2010.03358, Eqs. (4), (7), (8)) and at p_AP = 0 collapses onto _core.decoy_gain itself.</td><td>✅ pass</td></tr><tr><td><code>test_backflash_anchor</code></td><td>Published anchor, fitted e = 1.29%: Singh, Sharma, Singh and Prabhakar (arXiv:2502.04081) count 1598 backflashes in 18000 sifted, which backflash_leak returns as their P_b = 0.0888, and P_sec = P_sift(1 - P_b - f h(e)) at f = 1.16 reproduces their &quot;approximately 10%&quot; rate loss.</td><td>✅ pass</td></tr><tr><td><code>test_backflash_inefficiency</code></td><td>The house f = 1.16 (Lutkenhaus PRA 61, 052304 (2000), Table I) differs from Singh et al.&#39;s 1.15 by exactly 0.01*h(e) and security() carries f through, a probability outside [0, 1] is refused, and at Meda et al.&#39;s measured 6% and 9.8% (arXiv:1605.05562) the leak stays under the sift and the rate non-negative.</td><td>✅ pass</td></tr><tr><td><code>test_clip_refused</code></td><td>full_scale is 2*clip or None, and a declared clip is refused on homodyne and heterodyne alike, naming q.attacks.Saturation.</td><td>✅ pass</td></tr><tr><td><code>test_coherence_fringe</code></td><td>Cross-check, not a reproduction: at 50 MHz on a 1 GHz clock and d = 1, 2 periods, the simulated fringe is 0.98*coherence(lw, d/R) to 3e-3 and the simulated v_phase is phase_variance(lw, d/R) to 0.01.</td><td>✅ pass</td></tr><tr><td><code>test_dead_saturation</code></td><td>A non-paralysable detector saturates below 1/tau_d and a paralysable one falls past 1/tau_d, and at R tau_d = 5e-3 both lose under R^2 tau_d, the non-paralysable shedding R^3 tau_d^2 at second order and the paralysable half of it.</td><td>✅ pass</td></tr><tr><td><code>test_extinction_limit</code></td><td>The extinction QBER floor 2/(r+3) (Huang et al. arXiv:1206.6591, Eq. (5)) falls below 1e-5 by r = 1e6, reads 1.9% at 20 dB, only raises a given QBER, and refuses r = 0.</td><td>✅ pass</td></tr><tr><td><code>test_paralysable_paired</code></td><td>At zero dead time saturate returns one number on both branches, and q.Link refuses paralysable=True beside dead=0.0 by name.</td><td>✅ pass</td></tr><tr><td><code>test_partner_closed</code></td><td>Every closed-form click link refuses a partner detector, decoy_gain, sarg_gain, sarg_yield and dps_rate each taking one eta and one dark.</td><td>✅ pass</td></tr><tr><td><code>test_partner_fields</code></td><td>The partner split reads eta and dark alone, so a partner differing in dead_time or jitter is refused by field name on the sampled paths.</td><td>✅ pass</td></tr><tr><td><code>test_partner_split</code></td><td>Bob&#39;s second threshold detector reaches both sampled click engines and moves their outputs, while an equal pair is the one-detector run bit for bit.</td><td>✅ pass</td></tr><tr><td><code>test_security_dict</code></td><td>security() mirrors assemble_extra&#39;s omit-when-unknown rule, never emitting xi.</td><td>✅ pass</td></tr><tr><td><code>test_visibility_drift</code></td><td>Interference visibility is 1 at zero polarisation mismatch and falls through the 0.37 two-source floor between 11 and 69 degrees, and mean DGD goes as D sqrt(L), 1 ps over 100 km at 0.1 ps/sqrt(km).</td><td>✅ pass</td></tr></tbody></table>',4)])])}const u=e(r,[["render",o]]);export{_ as __pageData,u as default};
